tape( 'the function invokes a callback for each element in a 2-dimensional ndarray until the predicate returns a truthy value (row-major, non-contiguous, large arrays)', function test( t ) {
	var expected;
	var values;
	var bsize;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;

	dt = 'float64';
	ord = 'row-major';

	bsize = blockSize( dt );
	sh = [ bsize*2, 2 ];
	st = [ -4, 2 ];
	o = strides2offset( sh, st );

	x = ndarray( dt, zeros( numel( sh )*2, dt ), sh, st, o, ord );
	x.set( sh[0]-1, 0, 101.0 );

	values = [];
	untilEach( [ x ], predicate, fcn );

	expected = [];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v % 2.0 !== 0.0;
	}

	function fcn( v ) {
		if ( v !== 0.0 ) {
			values.push( v );
		}
	}
});

