	ord = 'row-major';

	bsize = blockSize( dt );
	sh = [ bsize*2, 2 ];
	st = [ -4, 2 ];
	o = strides2offset( sh, st );

	x = ndarray( dt, zeros( numel( sh )*4, dt ), sh, st, o, ord );
	x.set( sh[0]-1, 0, new Complex128( 101.0, 0.0 ) );

	values = [];
	untilEach( [ x ], predicate, fcn );

