tape( 'the function supports specifying the callback execution context (row-major, contiguous)', function test( t ) {
	var expected;
	var indices;
	var values;
	var arrays;
	var ord;
	var ctx;
	var sh;
	var st;
	var dt;
	var o;
	var x;

	dt = 'float64';
	ord = 'row-major';
	sh = [ 2, 2 ];
	st = shape2strides( sh, ord );
	o = strides2offset( sh, st );

	x = ndarray( dt, oneTo( numel( sh ), dt ), sh, st, o, ord );

	indices = [];
	values = [];
	arrays = [];

	ctx = {};
	untilEach( [ x ], predicate, fcn, ctx );

	expected = [ 1.0, 2.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [ [ 0, 0 ], [ 0, 1 ] ];
	t.deepEqual( indices, expected, 'returns expected value' );

	expected = [ x, x ];
	t.deepEqual( arrays, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v >= 3.0;
	}

	function fcn( v, idx, arr ) {
		t.strictEqual( this, ctx, 'returns expected context' ); // eslint-disable-line no-invalid-this
		values.push( v );
		indices.push( idx );
		arrays.push( arr );
	}
});

